def _state(label: str) -> str:
    """An exercise is failed when its own check failed, or when a table row below it disagreed with the answer key."""
    state = _STATUS.get(label, "not started")
    return "failed" if state == "passed" and _ROW_FAILS.get(label) else state


def _progress_board() -> None:
    """One line per exercise, from the latest run of its check and of the table rows that test it, then the tally."""
    width = max(len(", ".join(funcs)) for funcs in _EXERCISES.values())
    print("progress board")
    for label, funcs in _EXERCISES.items():
        state = _state(label)
        print(f"  {_MARKS[state]} {label:<12} {', '.join(funcs):<{width}}  {state}")
    done = sum(_state(label) == "passed" for label in _EXERCISES)
    print(f"\n{done} of {len(_EXERCISES)} exercises complete")
    failing = [label for label in _EXERCISES if _state(label) == "failed"]
    if failing:
        print("failing right now: " + ", ".join(failing) + ". Each one printed what went "
              "wrong in its own cell above, and every exercise has hints you can open.")
        rows = [f"{label}: {'; '.join(sorted(_ROW_FAILS[label]))}" for label in _EXERCISES if _ROW_FAILS.get(label)]
        if rows:
            print("a table below an exercise disagreed with the answer key (" + "; ".join(rows) + "): fix the function, "
                  "then re-run that table's cell, because the board reads its latest run.")
